import React, { useEffect, useState } from "react";
import axios from "axios";
import { useSearchParams } from "react-router-dom";
import RoomCard from "../components/RoomCard";

const CITIES = ["All Cities","Cairo","Alexandria","Giza","Hurghada","Sharm El Sheikh","Luxor","Aswan"];
const TYPES  = ["Entire apartment","Private room","Studio","Hotel room"];

export default function ExplorePage() {
  const [searchParams] = useSearchParams();
  const [rooms, setRooms]   = useState([]);
  const [loading, setLoading] = useState(true);

  const [filters, setFilters] = useState({
    city:     searchParams.get("city") || "",
    minPrice: "",
    maxPrice: "",
    maxGuests: searchParams.get("maxGuests") || "",
    type: "",
  });

  const [applied, setApplied] = useState({ ...filters });

  const fetchRooms = async (f) => {
    setLoading(true);
    try {
      const params = {};
      if (f.city && f.city !== "All Cities") params.city = f.city;
      if (f.minPrice)  params.minPrice  = f.minPrice;
      if (f.maxPrice)  params.maxPrice  = f.maxPrice;
      if (f.maxGuests) params.maxGuests = f.maxGuests;
      if (f.type)      params.type      = f.type;
      const { data } = await axios.get("/api/rooms", { params });
      setRooms(data.rooms);
    } catch { setRooms([]); }
    finally { setLoading(false); }
  };

  useEffect(() => { fetchRooms(applied); }, []);

  const apply = () => { setApplied({ ...filters }); fetchRooms(filters); };
  const reset = () => {
    const empty = { city: "", minPrice: "", maxPrice: "", maxGuests: "", type: "" };
    setFilters(empty); setApplied(empty); fetchRooms(empty);
  };

  const set = (k, v) => setFilters(p => ({ ...p, [k]: v }));

  return (
    <div style={{ display: "grid", gridTemplateColumns: "270px 1fr", minHeight: "calc(100vh - var(--nav-h))" }}>

      {/* ── Sidebar Filter ── */}
      <aside style={{
        borderRight: "1px solid var(--border)", padding: "24px 20px",
        background: "white", position: "sticky", top: "var(--nav-h)",
        height: "calc(100vh - var(--nav-h))", overflowY: "auto",
      }}>
        <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 20 }}>Filter Rooms</h3>

        {/* City */}
        <div style={{ marginBottom: 22 }}>
          <label style={{ fontSize: 10, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", color: "var(--muted)", display: "block", marginBottom: 10 }}>City</label>
          <select value={filters.city} onChange={e => set("city", e.target.value)}
            style={{ width: "100%", border: "1px solid var(--border)", borderRadius: "var(--r-sm)", padding: "8px 10px", fontFamily: "'Sora',sans-serif", fontSize: 13, outline: "none" }}>
            {CITIES.map(c => <option key={c}>{c}</option>)}
          </select>
        </div>

        {/* Price */}
        <div style={{ marginBottom: 22 }}>
          <label style={{ fontSize: 10, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", color: "var(--muted)", display: "block", marginBottom: 10 }}>Price / night ($)</label>
          <div style={{ display: "flex", gap: 8 }}>
            {[["minPrice","Min"],["maxPrice","Max"]].map(([k,ph]) => (
              <input key={k} type="number" placeholder={ph} value={filters[k]}
                onChange={e => set(k, e.target.value)}
                style={{ flex: 1, border: "1px solid var(--border)", borderRadius: "var(--r-sm)", padding: "8px 10px", fontFamily: "'Sora',sans-serif", fontSize: 13, outline: "none" }} />
            ))}
          </div>
        </div>

        {/* Room Type */}
        <div style={{ marginBottom: 22 }}>
          <label style={{ fontSize: 10, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", color: "var(--muted)", display: "block", marginBottom: 10 }}>Room Type</label>
          {TYPES.map(t => (
            <div key={t} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 9 }}>
              <input type="checkbox" checked={filters.type === t} onChange={() => set("type", filters.type === t ? "" : t)}
                style={{ accentColor: "var(--gold)", width: 15, height: 15 }} />
              <label style={{ fontSize: 13, cursor: "pointer" }}>{t}</label>
            </div>
          ))}
        </div>

        {/* Max Guests */}
        <div style={{ marginBottom: 22 }}>
          <label style={{ fontSize: 10, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", color: "var(--muted)", display: "block", marginBottom: 10 }}>Max Guests</label>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            {["Any","1","2","3","4+"].map(g => (
              <button key={g} onClick={() => set("maxGuests", g === "Any" ? "" : g.replace("+",""))}
                style={{
                  minWidth: 36, height: 36, border: "1px solid var(--border)", borderRadius: "var(--r-sm)",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 12, fontWeight: 600, cursor: "pointer", padding: "0 8px",
                  background: (filters.maxGuests === g.replace("+","") || (g === "Any" && !filters.maxGuests)) ? "var(--gold)" : "white",
                  color:      (filters.maxGuests === g.replace("+","") || (g === "Any" && !filters.maxGuests)) ? "white" : "var(--muted)",
                  borderColor:(filters.maxGuests === g.replace("+","") || (g === "Any" && !filters.maxGuests)) ? "var(--gold)" : "var(--border)",
                  transition: "all .15s",
                }}>{g}</button>
            ))}
          </div>
        </div>

        {/* Buttons */}
        <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
          <button className="btn btn-dark" onClick={apply}  style={{ flex: 1, justifyContent: "center", padding: "10px", fontSize: 13 }}>Apply Filters</button>
          <button className="btn btn-out"  onClick={reset}  style={{ padding: "10px 14px", fontSize: 13 }}>Reset</button>
        </div>
      </aside>

      {/* ── Results ── */}
      <div style={{ padding: "24px 28px", background: "var(--cream)" }}>
        {/* Map Strip placeholder */}
        <div style={{
          marginBottom: 20, height: 140, borderRadius: "var(--r-lg)", overflow: "hidden",
          background: "linear-gradient(135deg,#C8D4C0 0%,#8FAF85 50%,#6B8B62 100%)",
          display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: 14, color: "rgba(0,0,0,.45)", fontWeight: 500,
          border: "1px solid var(--border)", position: "relative",
        }}>
          <span style={{ position: "absolute", top: "33%", left: "22%" }}>📍</span>
          <span style={{ position: "absolute", top: "48%", left: "52%" }}>📍</span>
          <span style={{ position: "absolute", top: "28%", left: "68%" }}>📍</span>
          Map View · {applied.city || "Egypt"}
        </div>

        {/* Top bar */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
          <div>
            <h2 style={{ fontSize: 17, fontWeight: 600 }}>{applied.city || "All"} Rooms</h2>
            <p style={{ fontSize: 13, color: "var(--muted)" }}>{rooms.length} rooms found</p>
          </div>
          <select style={{ border: "1px solid var(--border)", borderRadius: "var(--r-sm)", padding: "8px 12px", fontFamily: "'Sora',sans-serif", fontSize: 13, background: "white", outline: "none" }}>
            <option>Best match</option>
            <option>Price: Low–High</option>
            <option>Price: High–Low</option>
            <option>Highest Rated</option>
          </select>
        </div>

        {/* Grid */}
        {loading ? (
          <div style={{ textAlign: "center", padding: "60px 0", color: "var(--muted)" }}>Loading rooms…</div>
        ) : rooms.length === 0 ? (
          <div style={{ textAlign: "center", padding: "60px 0", color: "var(--muted)" }}>
            <div style={{ fontSize: 48, marginBottom: 16 }}>🔍</div>
            <p>No rooms found. Try adjusting your filters.</p>
          </div>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 18 }}>
            {rooms.map((room, i) => <RoomCard key={room._id} room={room} index={i} />)}
          </div>
        )}
      </div>
    </div>
  );
}
